PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?spouse ?spouseLabel ?mother ?motherLabel WHERE {
  { dbr:Felicia_of_Roucy dbo:spouse ?spouse } UNION { dbr:Felicia_of_Roucy dbp:spouse ?spouse } .
  OPTIONAL {
    { ?spouse dbo:mother ?mother } UNION { ?spouse dbp:mother ?mother } .
  }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel FILTER(lang(?spouseLabel) = 'en') }
  OPTIONAL { ?mother rdfs:label ?motherLabel FILTER(lang(?motherLabel) = 'en') }
}

